import functools

import jax
import jax.numpy as jnp
import numpy as np

from deciax.models.clef.head import forward, means
from tests.conftest import FIXTURES


def test_joint_head_matches_cloudflare_with_mixed_schema_padding() -> None:
    """Fixture: pinned Cloudflare head, generated by scripts/clef_head_fixture.py."""
    with np.load(FIXTURES / "clef_head.npz") as fixture:
        params = {k.removeprefix("param."): jnp.asarray(v) for k, v in fixture.items() if k.startswith("param.")}
        arrays = {k.removeprefix("array."): jnp.asarray(v) for k, v in fixture.items() if k.startswith("array.")}
        hidden = jnp.asarray(fixture["hidden"])
        lexical = means(jnp.asarray(fixture["embedding"])[arrays["lexical_ids"]], arrays["lexical_spans"])

        apply = jax.jit(functools.partial(forward, heads=4, routing_layers=2, layers=2))
        output = np.asarray(apply(params, hidden, lexical, arrays))

        for i in range(3):
            expected = fixture[f"expected.{i}"]
            np.testing.assert_allclose(output[i, : len(expected)], expected, atol=3e-6, rtol=3e-5)

        # Padding state cannot leak into genuine fields/options.
        changed = jnp.where(arrays["mask"][..., None], hidden, 10000.0)
        second = np.asarray(apply(params, changed, lexical, arrays))
        np.testing.assert_allclose(output[:3], second[:3], atol=1e-6)
